const STREETS: [&str; 6] = ["Via Roma", "Via Po", "Corso Francia", "Via Nizza", "Via Garibaldi", "Corso Vinzaglio"];

fn generate_plan(count_visits: usize, count_routes: usize) -> Plan {
    let visits = (0..count_visits)
        .map(|idx| Visit {
            id: format!("visit-{idx}"),
            name: format!("{} {}", STREETS[idx % STREETS.len()], 1 + idx * 3),
        })
        .collect::<Vec<_>>();

    // Room for every visit, with a little slack, unevenly spread.
    let routes = (0..count_routes)
        .map(|idx| Route {
            id: format!("route-{idx}"),
            name: format!("Van {}", idx + 1),
            capacity: count_visits.div_ceil(count_routes) + idx % 3,
            visits: Vec::new(),
        })
        .collect::<Vec<_>>();

    Plan::new(visits, routes)
}
